(* [comment removed for export] *)
Definition glp_rows (data wpl : Z) (n : nat) : list word := map (fun j => Z_to_bv 64 (data + 4 * wpl * Z.of_nat j)) (seq 0 n).
Lemma glp_rows_S : forall data wpl n, glp_rows data wpl (S n) = glp_rows data wpl n ++ [Z_to_bv 64 (data + 4 * wpl * Z.of_nat n)].
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_lineptrs_loop ()) [] "h01jh11lh24datah31nh43wplp;1p;2p;3p;4p;5p;6g0000R0p4p7210g000LR1p4p710p8g000jj1=Tg001Jj27Tg001fj2ATg002=j1:Tg002]j38Tg003=j33Tg003Zj11Tg004?j1@Tg004]j1?Tg005@j1>Tg005^j20Tg006;j19Tg006[j25Tg0078j24Tg007^j42Tg008:j36Tg008Tj2ETP0j5DTP1j6<Tg008nj1CTg009Mj2BTg009gj3;Tg00:lR1g00;JR0%=0R2g00;iR3f0R4'7R51A34%:0580R6530R7g00<H#1#1R8#1#1#1#1#@R9#?R:#=R;P0P:f4%>8R8f3R<'0%94R='0'5,49X00R>P4C2P0P:P>f1R>,73C2f2R?,08R@%9>'0,5<,49%::RA58:53:RB36X12P;P0P:10@=,5<,49X00R<P5C2R@P0P:P<P6C253:A6;4BX1;108>/0=,5?,49=8:ARA93:@,E;P0P:P<P7C2P0P:P<P5P6DDE<%C4R6,731B43E<A;?>6A;?>4=3:A56;eW3X41W2o"). Qed.
