(* [comment removed for export] *)
Definition glp_exit (ra sp gp tp t0 t1 t2 s0 s1 a4 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lp data wpl h : Z) : machine_state -> Prop :=
  fun ms' => exists (a1' a2' a3' a5' a6' s2' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 lp) a1' a2' a3' a4 a5' a6' a7 s2' s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x9cbc8) fc None m' (seg_rom asegs)
    /\ munch [(lp, lp + 8 * h)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u64arr asegs m' lp (glp_rows data wpl (Z.to_nat h)).

Lemma glp_loop : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (lp data wpl h : Z),
  Z.of_nat k = h - i -> 0 <= i -> (1 <= k)%nat -> 0 < h <= 20000 -> 0 < wpl <= 2^20 -> 0 <= data -> data + 4 * wpl * h <= 2^47 ->
  0 < lp -> lp mod 8 = 0 -> lp + 8 * h <= 2^47 -> (lp + 8 * h <= 0x7fff7000 \/ 0x10007fff8000 <= lp) ->
  u64arr asegs m lp (glp_rows data wpl (Z.to_nat i)) -> wr_at asegs m lp (8 * h) -> acc asegs m lp (8 * h) -> mem_inv asegs m ->
  evt asegs (glp_exit ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (wpl * 4)) a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m lp data wpl h)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 lp) (Z_to_bv 64 (lp + 8 * i)) (Z_to_bv 64 (data + 4 * wpl * i)) (Z_to_bv 64 (h - i))
             (Z_to_bv 64 (wpl * 4)) (Z_to_bv 64 (lp + 8 * i)) a6 a7 (Z_to_bv 64 ((lp + 8 * i) / 8 + 2147450880))
             s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
